
-- --------------------------------------------------------

--
-- Table structure for table `shows`
--

CREATE TABLE `shows` (
  `id` tinyint(2) UNSIGNED NOT NULL COMMENT 'Unique identifier',
  `inactive` tinyint(1) UNSIGNED DEFAULT NULL COMMENT 'Binary indicator for whether the show is now inactive.',
  `sort_order` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'Sort order for index page.',
  `name` varchar(64) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Show name',
  `english_name` varchar(64) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'English translation of name',
  `overseas_names` varchar(512) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Alternate names for the show in other countries.',
  `country` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Country of production',
  `language` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Primary language spoken in the show.',
  `flag` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Flag image file name for nation of production.',
  `start_year` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Year of first season',
  `end_year` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Year of last season.',
  `episode_length_notes` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Episode length notes',
  `website` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Website link',
  `imdb` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'IMDb link',
  `wikipedia` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Wikipedia link',
  `instagram` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Instagram link',
  `youtube` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'YouTube link',
  `description` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Description (use pipes to separate paragraphs)',
  `contestants_notes` varchar(2048) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Contestant panel size notes (pipe-separated).',
  `team_task_notes` varchar(2048) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Team task notes',
  `tiebreaks_notes` varchar(2048) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Tiebreak notes',
  `prizes_notes` varchar(2048) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Episode prize notes (pipe-separated).',
  `awards_notes` varchar(2048) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Details of any awards won by the show (pipe-separated bullets).',
  `notes` varchar(4096) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Bullet point notes (use pipes to separate bullets).',
  `cover_image_framed` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Framed version of cover image.',
  `cover_image_metatag` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Cover image filename for metatags only',
  `cover_image_thumb` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Cover image thumbnail filename',
  `cover_image_description` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Cover image description',
  `wax_seal_image` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Wax seal image filename.',
  `trophy_image` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Image file for show trophy.'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

--
-- Dumping data for table `shows`
--

INSERT INTO `shows` (`id`, `inactive`, `sort_order`, `name`, `english_name`, `overseas_names`, `country`, `language`, `flag`, `start_year`, `end_year`, `episode_length_notes`, `website`, `imdb`, `wikipedia`, `instagram`, `youtube`, `description`, `contestants_notes`, `team_task_notes`, `tiebreaks_notes`, `prizes_notes`, `awards_notes`, `notes`, `cover_image_framed`, `cover_image_metatag`, `cover_image_thumb`, `cover_image_description`, `wax_seal_image`, `trophy_image`) VALUES
(1, 0, 2, 'Taskmaster UK', NULL, 'On Sweden\'s SVT Play service, and on Sweden\'s TV4 Play service, this show is titled \'Bäst i test England\' (Best in Test England).|On Denmark\'s TV2 Play service, it is titled \'Stormester UK\' (Grandmaster UK).|On Finland\'s MTV Katsomo service, it is titled \'Suurmestari UK\' (Grandmaster UK).|On Croatia\'s RTL Play service, it is known as \'Direktor Svemira UK\' (Director of the Universe UK).|On Norway\'s Discovery+ service, this show is titled \'Kongen Befaler UK\' (The King Commands UK).', 'UK', 'English', NULL, 2015, NULL, '44 - 48 min', 'https://taskmaster.tv/', 'https://www.imdb.com/title/tt4934214/', 'https://en.wikipedia.org/wiki/Taskmaster_(TV_series)', 'https://www.instagram.com/taskmaster/', 'https://www.youtube.com/taskmaster', 'Taskmaster is a British comedy panel game show created by the British comedian Alex Horne during the Edinburgh Festival Fringe in 2010, and adapted for television in 2015. New episodes premiered on the Dave TV channel between 2015 and 2019, when the show was acquired by Channel 4. The show stars comedian and actor Greg Davies in the title role of the Taskmaster, issuing simple comedic and bizarre tasks to five regular contestants – usually comedians – with Alex Horne acting as assistant to Davies and as umpire during the challenges.', 'The panel consists of five fixed contestants per season.|Contestants have so far only returned for Champion of Champions specials, to make up numbers in team tasks requiring three members on each team, or as in-studio stand-ins for contestants who are ill.', 'Team tasks are completed by uneven teams of two and three contestants.|In rare circumstances where three members are needed on each team for a task, a former contestant may return to make up the numbers.', 'Episode ties are broken through tiebreaker tasks, either pre-recorded or live in studio.', 'A prize pool is established for each episode from items brought in by contestants for the prize task.|The prizes are typically presented on screen, though there have been a few occasions where they have been presented on stage.', 'British Academy of Film and Television Arts (BAFTA) Television Award, in the category of Best Comedy Entertainment Programme (2020)|British Academy of Film and Television Arts (BAFTA) Television Craft Award, in the category of Entertainment Craft Team - awarded to director Andy Devonshire, editor Rebecca Bowker, production designer James Dillon, and composer Dru Masters (2025)|British Comedy Guide Awards, in the category of Best TV Entertainment Show (2016, 2017, 2018, 2020, 2021, 2022, 2023, 2024)|British Comedy Guide Award, in the category of Comedy of the Year (2021)|Chortle Awards in the categories of Best TV Show and Outstanding Achievement (2024)|National Comedy Awards, in the category of Best Comedy Entertainment Show (2022, 2023)|Televisual Bulldog Awards, in the Comedy category (2023)|Rose d\'Or Award, in the category of Comedy Entertainment (2024)', 'In episode 13 of the Taskmaster podcast, Alex Horne revealed that, in early versions of the pitches for Taskmaster as a TV show, the plan was to have 10 contestants per series (like in the second year of the live Edinburgh show).|According to Alex, once the decision was made to reduce this to five, there were plans to have the contestants seated in a ‘hive structure’ above the stage, and brought down one at a time to complete tasks.|Alex has stated on multiple occasions that the first series of the show was only possible once he had secured Frank Skinner as a contestant, after which Greg Davies was fully on-board.|Alex has also shared that, in persuading the first contestants to agree to appear on the show, he disclosed as an example the task where they had to fill an egg cup with tears.|In episode 44 of the Taskmaster podcast it was revealed that, in 2015, prior to the shooting of the first series, Phil Wang had been brought in to the Taskmaster house as a task-tester. Phil tested some of the tasks which made it into the first two series, including: the \'Eat as much watermelon as possible\' task, from series 1, in which he smashed the melon up with a baseball bat; and the \'Order a pizza without using certain words\' task, from series 2, which he found excruciatingly embarrassing.', '01_taskmaster_uk_framed.png', '01_taskmaster_uk_metatag.jpg', '01_taskmaster_uk_thumb.jpg', 'Cover image for the UK show Taskmaster, showing the hosts of the show, Greg Davies and Alex Horne.', '01_taskmaster_uk_seal.jpg', '01_taskmaster_uk_trophy.jpg'),
(2, 1, 3, 'Het Grootste Licht', 'The Brightest Bulb', NULL, 'Belgium', 'Dutch', NULL, 2016, 2016, '51 - 59 min', 'https://www.demensen.be/nl/producties/het-grootste-licht', 'https://www.imdb.com/title/tt29475260/', NULL, NULL, NULL, 'Het Grootste Licht is the Flemish version of the successful British TV show Taskmaster. Gert Verhulst and his personal assistant Ruth Beeckmans take pleasure in having 5 famous Flemish people carry out all kinds of bizarre tasks.', 'The panel consists of four fixed contestants, and a different guest contestant in each episode.|Since no attention was paid to the contestants\' cumulative scores throughout the season, and no season winner was crowned, the question of whether the guest contestants were considered a team is moot.', 'Team tasks are completed by uneven teams of two and three contestants.|In rare circumstances where three members are needed on each team for a task, another guest contestant may be brought in to make up the numbers.', 'Episode ties are broken through tiebreaker tasks carried out live in studio.', 'A prize pool is established for each episode from items brought in by contestants for the prize task.|The contestants physically present their items in-studio.', NULL, NULL, '02_het_grootste_licht_framed.png', '02_het_grootste_licht_metatag.jpg', '02_het_grootste_licht_thumb.jpg', 'Cover image for the Belgian show Het Grootste Licht, showing the hosts of the show, Gert Verhulst and Ruth Beeckmans.', '02_het_grootste_licht_seal.jpg', NULL),
(3, 0, 4, 'Bäst i Test', 'Best in Test', 'On Finland\'s MTV Katsomo service, this show is titled \'Suurmestari Ruotsi\' (Grandmaster Sweden).', 'Sweden', 'Swedish', NULL, 2017, NULL, '57 - 59 min', 'https://www.tv4play.se/program/656771bf6316036b7178/bast-i-test', 'https://www.imdb.com/title/tt8002676/', 'https://sv.wikipedia.org/wiki/B%C3%A4st_i_test_(TV-program)', 'https://www.instagram.com/bastitest_tv/', NULL, 'Bäst i Test is the Swedish version of the British TV show Taskmaster, produced by the production company <a href=\"https://baluba.se/\">Baluba</a>.|The Taskmaster role is held by Babben Larsson, and she is assisted by David Sundin.|Until the seventh season, which first aired in 2023, the show was commissioned by and broadcast on the SVT channel in Sweden. However, beginning in 2024, the rights to the format are owned by the competing commercial channel, TV4.', 'In seasons 1 through 7, the panel consists of four fixed contestants, and a different guest contestant in each episode. A representative of the production company, Baluba, shared that this allowed them to have the best of both worlds - both continuity across the season, and variety between episodes.|From season 8, there is no weekly guest contestant, but a fixed panel of five contestants throughout each season, plus a consistent single guest contestant throughout the season who only appears in team tasks, to make the teams even.|There has not yet been a Champion of Champions special, featuring the winners of previous seasons, but there has been a single episode Sämst i Test (Worst in Test) special, featuring 5 of the lowest-scoring contestants.|People who previously appeared as guest contestants in a season have also reappeared in a later season as fixed contestants.|Prior to the move to TV4, and the adoption of a fixed panel of five guests per season, the worst-performing fixed contestant in each season would also return as a guest contestant in the following season, as an opportunity for redemption.|Previous contestants have also returned as in-studio stand-ins for contestants who are ill and, since season 8, to even out the teams in team tasks.|In seasons 1 through 7, the guest contestants were considered a team, for the purposes of the season scores, and so were able to win the season (and did so, once).', 'In seasons 1 through 7, team tasks are only completed by the fixed contestants of each season, in even teams of two, and the guest contestant in each episode may earn points by correctly predicting which of the teams will win the task.|Starting in season 8, since there is no weekly guest contestant anymore, team tasks are completed by all contestants, but the teams are kept even by inviting back another previous contestant to make the team of two up to a team of three.', 'Episode ties have sometimes been broken through tiebreaker tasks, either pre-recorded or live in studio, but have also sometimes been left as ties.', 'In the first two seasons, a prize pool was established for each episode from items brought in by contestants for the prize task.|In season 2, the prize task was moved to later in the show, so reduce the wait between the start of the episode and the appearance of the first pre-filmed task.|From season 3 onwards, the prize task was removed from the format altogether, in favour of a joke prize - usually relating to something that happened during one of the other tasks - selected by the production team.', 'Season 3: Kristallen award in the category Programme of the Year (2019)|Season 4: Kristallen award in the category Best Entertainment Programme (2020)|Season 4: Children\'s Prize at Barncancergalan – Det svenska humorpriset [The Children\'s Cancer Gala - The Swedish Humour Prize] (2020)', 'The show\'s name is also a phrase used frequently in consumer reviews, referring to the best product tested in a specific category. It was chosen because Swedish has no equivalent word for \'Taskmaster\', and also because the word \'task\' is slang for \'penis\' in Sweden.|The first season of the show only had four episodes because SVT had also commissioned four episodes of another show, <em>Gissa låten</em> (‘Guess the song’), to see which of the two formats performed better in the time slot. <em>Gissa låten</em> ultimately ended up performing much worse than Bäst i Test, which then got eight episodes for its second season.|Instead of sitting next to one another in throne-like chairs, the hosts have adjoining wooden desks, with David Sundin (the Taskmaster’s assistant) occupying a significantly smaller one than the Taskmaster herself.|Until the fourth series, the contestants, rather than being seated on separate chairs, occupied two sofas (one three-seater, and one two-seater). This changed to separate seats in the fifth series, presumably due to social distancing precautions during the Covid-19 pandemic, but reverted back in season 6.|Regarding the studio design, a representative of the production company Baluba stated that \"We wanted the studio to feel more primetime weekend. More like a living room and less like a stage. And we thought that people sitting in chairs looked a bit stiff and less inviting. The desks are mainly there to show status differences between the two hosts but also towards the contestants.\"|The show features an additional live task each episode, in a segment known as ‘Middle of the Show’, which begins with David badly interviewing the episode’s guest contestant in order to force a pun-based segue into the title of the task.|The title sequence for each episode features clips exclusively from that episode.|The final scoreboards in many episodes prior to season 8 may be seen not to match the points that were observed to be awarded during the episode. These discrepancies were addressed broadly on SVT\'s website, where it stated: \"Sometimes an episode\'s final score does not match the points that have been reported in the programme. This is because we record more tests than are included in an episode. This is to insure us in case something should go wrong. It will be the correct winner, and it will be especially right at the end of the series when we will crown the winner of Babben\'s bust. Most of the clipped tests will be shown in a separate bonus episode, episode 10.\"|The prize trophy in the show is a full and heavy golden bust of Babben Larssen, of which there is only one copy (i.e. the contestants do not get to take it home with them).', '03_bast_i_test_framed.png', '03_bast_i_test_metatag.jpg', '03_bast_i_test_thumb.jpg', 'Cover image for the Swedish show Bäst i Test, showing the hosts of the show, Babben Larsson and David Sundin.', '03_bast_i_test_seal.jpg', '03_bast_i_test_trophy.jpg'),
(4, 0, 8, 'Kongen Befaler', 'The King Commands', 'On Sweden\'s SVT Play service, this show was titled \'Bäst i test Norge\' (Best in Test Norway).|On Australia\'s SBS On Demand service, this show is titled \'Taskmaster Norway\'.', 'Norway', 'Norwegian', NULL, 2019, NULL, '40 - 45 min', 'https://www.discoveryplus.com/no/show/kongen-befaler', 'https://www.imdb.com/title/tt13218362/', 'https://no.wikipedia.org/wiki/Kongen_befaler_(TV-program)', 'https://www.instagram.com/kongen.befaler_tvnorge/', NULL, 'Kongen Befaler is the Norwegian version of the British TV show Taskmaster, produced by <a href=\"https://nordiskbanijay.no\">Nordisk Banijay</a> since season 2, and broadcast on discovery+ and TVNorge.|The Taskmaster role is held by Atle Antonsen, except for in season 7, when it was held by season 1 contestant Bård Ylvisaker.|The assistant role is held by  Olli Wermskog.', 'The panel consists of five fixed contestants per season.|The only case of return contestants so far has been the return of <a href=\"/season.php?id=17\">season 1</a> contestants <a href=\"/person.php?id=114\">Calle Hellevang-Larsen</a> and <a href=\"/person.php?id=113\">Maria Stavang</a> in <a href=\"/season.php?id=18\">season 2</a>. According to show producer Bjørn Håvard Mittet, of Nordisk Banijay, these contestants returned for a second season at Discovery\'s request, as both of them are affiliated with the network. However, five former contestants are also due to return for a four-episode special mini-season, which is currently in production, as of late 2023.|Contestants are not seated in alphabetical order on stage, but instead seated with the intent of getting the best possible dynamics between them, according to Bjørn.|Contestants have remained seated in the same order throughout their seasons except for in season 3, which was recorded without an audience. According to Bjørn, the production team wanted to test whether changing the seating order would have any effect on the dynamics between them, so switched them around from episode to episode, during this season.', 'There were no team tasks in this version of the show until season 6.|According to show producer \r\nBjørn Håvard Mittet, the reason for the absence of team tasks until this point was largely due to social distancing requirements during the Covid-19 pandemic. However, team tasks have not become a regular occurrence in more recent seasons.', 'There are no tie-breakers in this version of the show. Episodes with tied scores are left as draws, with the contestants sharing the prize pool.|According to show producer Bjørn Håvard Mittet, the reason for the absence of tie-breakers is partially down to the tight filming schedule for the live studio segments (90 minutes per episode), and partially down to the feeling that the tie-breakers would not add much value to the episode. He notes, though, that some live studio tasks have had tie-breaker rounds included within them, and that a tie-breaker was also used in the cancelled 2022 Christmas special.', 'A prize pool is established for each episode from items brought in by contestants for the prize task.|Instead of just being shown on screen, the contestants\' items are revealed on stage from beneath red cloth.', 'Gullruten TV award in the category of Best Entertainment Programme (2020 & 2022)|Gullruten TV award in the category of Best Comedy Programme (2024)', 'The show\'s title translates into English as \"The King Commands\", and is the Norwegian name of the game Simon Says.|At the end of art tasks, the contestants typically present their creations in the studio, rather than just an image of the work appearing on screen.|Except for in the very first episode of the first season, and in the live tasks in the second season, the task briefs are always read out by Olli Wermskog, the Taskmaster\'s assistant, rather than one of the contestants.', '04_kongen_befaler_framed.png', '04_kongen_befaler_metatag.jpg', '04_kongen_befaler_thumb.jpg', 'Cover image for the Norwegian show Kongen Befaler, showing the current hosts of the show, Atle Antonsen and Olli Wermskog.', '04_kongen_befaler_seal.jpg', '04_kongen_befaler_trophy.jpg'),
(5, 1, 5, 'Dicho y Hecho', 'Said and Done', NULL, 'Spain', 'Spanish', NULL, 2018, 2018, '108 - 140 min', 'https://www.rtve.es/television/dicho-y-hecho/', 'https://www.imdb.com/title/tt8095850/', 'https://es.wikipedia.org/wiki/Dicho_y_hecho_(programa_de_televisi%C3%B3n)', 'https://www.instagram.com/dichoyhechotve/', NULL, 'Dicho y Hecho was the Spanish version of the British TV show Taskmaster, featuring Anabel Alonso in the Taskmaster role, and José Corbacho as her assistant. It was produced by and aired on the La 1 TV channel, but was cancelled before production of the series was completed, after just five (of eight total planned) episodes, due to low audiences. In contrast to other versions of the show, Dicho y Hecho featured six contestants in each episode. Another major difference was the length of the episodes, clocking in at around two hours each (apparently not an uncommon length for a Spanish prime time entertainment show). With such long episodes, each featured the contestants completing seven tasks, four of which were pre-recorded, and three of which were completed live in the studio.', 'The panel consisted of six fixed contestants.', 'Team tasks are completed by even teams of three contestants.', 'There were no tied episodes in this version of the show, so it is not known if or how they might have been settled.', 'A prize pool is established for each episode from items brought in by contestants for the prize task.|The prizes are typically presented on screen.|The prizes are presented in pairs throughout the show, rather than all being discussed in one go together at the start of the episode.', NULL, NULL, '05_dicho_y_hecho_framed.png', '05_dicho_y_hecho_metatag.jpg', '05_dicho_y_hecho_thumb.jpg', 'Cover image for the Spanish show Dicho y Hecho, showing the hosts of the show, Anabel Alonso and José Corbacho.', '05_dicho_y_hecho_seal.jpg', NULL),
(6, 0, 7, 'Stormester', 'Grandmaster', 'On Sweden\'s TV4 Play service, this show is titled \'Bäst i test Danmark\' (Best in Test Denmark).', 'Denmark', 'Danish', NULL, 2018, NULL, '55 - 65 min', 'https://play.tv2.dk/serie/stormester-tv2', 'https://www.imdb.com/title/tt10353060/', 'https://da.wikipedia.org/wiki/Stormester_(tv-program)', 'https://www.instagram.com/stormester_tv/', NULL, 'Stormester is the Danish version of the British TV show Taskmaster. It is produced by <a href=\"https://metronome.dk/\">Metronome Productions</a>, and broadcast on the <a href=\"https://tv2.dk/\">TV2</a> channel in Denmark, which commissions the show on an annual basis. Lasse Rimmer plays the role of the titular Stormester, with Mark Le Fêvre assuming the role of his assistant.', 'The panel consists of five fixed contestants per season.|Up until 2023, contestants had only ever returned to the show for Christmas specials (which are actually filmed at the same time as their full seasons).|In 2023 and 2024, however, Stormester aired two special mini-seasons, both featuring contestants who had appeared in previous seasons: the \'Vindernes Vinder\' (\'Champion of Champions\') special, and the \'En Chance Til\' (\'One More Chance\') special.', 'There were not any pre-filmed team tasks in this version of the show until the \'Vindernes Vinder\' special. However, there had previously been a few live team tasks.|According to a representative of Metronome Productions, the decision not to include pre-filmed team tasks in early seasons was made primarily for budgetary reasons, since it would require additional days of filming in the Stormester house.', 'There are no tie-breaker tasks in this version of the show. Instead, tied episodes are decided based upon which contestant won the most tasks.|According to a representative of Metronome Productions, a likely fall-back method for deciding the episode, should two contestants have both the same number of points and task wins, would be to compare how many second places each of them had secured during the episode.', 'There is no prize task in this version of the show. Instead, a prize is put up by a different contestant each week, on a rotating basis.|Since there are five contestants and typically seven episodes, this means that some contestants submit more prizes than others.|According to a representative of Metronome Productions, the decision not to include a prize task in the show was made because panel shows are not well-established as a format in Denmark, so there was a desire \'get the show going\' more quickly, by launching straight into pre-filmed tasks.', 'Season 1: TV Prisen award in the category of Best Game Show (2019)|Season 2: TV Prisen award in the category of Best Game Show (2020)|Season 3: <em>Billedbladet</em> reader award in the category of Best Entertainment Programme (2021)|Season 5: TV Prisen award in the category of Best Game Show (2022)', 'The final filmed and broadcast episode of each season is typically a Christmas special. Although the same contestants are involved, and they are filmed along with the rest of the season, they are treated as separate specials on this site, since they broadcast months later than the rest of the season, and the season winner has already been decided in the preceding episode.|The location chosen as the Stormester house, for production of the pre-filmed tasks for the show, has switched locations several times so far, mainly due to the availability of the properties.|The venue used for production of the live studio segments of the show has also changed: The Court Theatre (\'Hofteateret\') was used for seasons 1 to 4, and the Glassalen (\'Glass House\') in the Tivoli Gardens amusement park has been the venue of choice - primarily due to the much larger seating capacity - since season 5. The live recordings for the \'Vindernes Vinder\' and \'En Chance Til\' specials took place in The Circus Revue (\'Cirkusrevyen\') tent in the Bakken amusement park, as the Tivoli venue was not available.|Each contestant spends four days filming tasks in the house, and attempts approximately ten tasks each day.|In each season, three or four more tasks are filmed than there is room for in the finished episodes, just in case some of them don\'t turn out to be very entertaining.|In order to prevent the overuse of loopholes that make the show less interesting, sometimes there are additional rules for tasks which are not necessarily shown being read out in the final edit.', '06_stormester_framed.png', '06_stormester_metatag.jpg', '06_stormester_thumb.jpg', 'Cover image for the Danish show Stormester, showing the hosts of the show, Lasse Rimmer and Mark Le Fêvre.', '06_stormester_seal.jpg', '06_stormester_trophy.jpg'),
(7, 1, 6, 'Taskmaster US', NULL, NULL, 'US', 'English', NULL, 2018, 2018, '21 - 22 min', 'https://www.cc.com/shows/taskmaster', 'https://www.imdb.com/title/tt8272292/', 'https://en.wikipedia.org/wiki/Taskmaster_(American_TV_series)', NULL, NULL, 'Taskmaster was a US comedy panel game show, based on the UK TV show of the same name. The American adaptation was produced in California for Comedy Central in 2017. It starred comedian and actor Reggie Watts as the Taskmaster, issuing simple comedic and bizarre tasks to regular contestants, and Alex Horne as his assistant. Since the episodes were only 30 minutes long, including ad breaks (just 21 minutes in actual run time), there was only time for three tasks per episode. The show did not perform well in the ratings, and there are no plans to produce a second season.', 'The panel consists of five fixed contestants.', 'There are no pre-filmed team tasks in this version of the show.', 'Episode ties are broken through tiebreaker tasks carried out live in studio.', 'There is no prize task in this version of the show.|Instead, a prize is put up by a different member of the cast (both contestants and hosts) for each episode.|Since there are only seven cast members, and eight episodes, the prize in the final episode was a collection of memorabilia from the show.', NULL, NULL, '07_taskmaster_us_framed.png', '07_taskmaster_us_metatag.jpg', '07_taskmaster_us_thumb.jpg', 'Cover image for the US show Taskmaster US, showing the hosts of the show, Reggie Watts and Alex Horne.', '07_taskmaster_us_seal.jpg', '07_taskmaster_us_trophy.jpg'),
(8, 0, 10, 'Taskmaster NZ', NULL, 'On Sweden\'s SVT Play service, and on Sweden\'s TV4 Play service, this show is titled \'Bäst i test Nya Zeeland\' (Best in Test New Zealand).|On Norway\'s Discovery+ service, this show is titled \'Kongen Befaler New Zealand\' (The King Commands New Zealand).', 'New Zealand', 'English', NULL, 2020, NULL, '43 - 46 min', 'https://www.tvnz.co.nz/shows/taskmaster-nz', 'https://www.imdb.com/title/tt13544772/', 'https://en.wikipedia.org/wiki/Taskmaster_(New_Zealand_TV_series)', 'https://www.instagram.com/taskmasternewzealand/', NULL, 'Taskmaster NZ is New Zealand’s version of the British show Taskmaster. The New Zealand adaptation is produced for TVNZ, with support from NZ On Air. The show is hosted by Taskmaster Jeremy Wells with comedian Paul Williams serving as his assistant. Following the format of the original British version, the show consists of five contestants who compete in a series of strange and unusual tasks to gain points from the Taskmaster.', 'The panel consists of five fixed contestants per season.', 'Team tasks are completed by uneven teams of two and three contestants.', 'Episode ties are broken through tiebreaker tasks, either pre-recorded or live in studio.', 'A prize pool is established for each episode from items brought in by contestants for the prize task.|The prizes are typically presented on screen, though there have been a few occasions where they have been presented on stage.', 'Best Entertainment Programme award at the 2023 NZ TV Awards.', NULL, '08_taskmaster_nz_framed.png', '08_taskmaster_nz_metatag.jpg', '08_taskmaster_nz_thumb.jpg', 'Cover image for the New Zealand show Taskmaster NZ, showing the hosts of the show, Jeremy Wells and Paul Williams.', '08_taskmaster_nz_seal.jpg', '08_taskmaster_nz_trophy.jpg'),
(9, 0, 9, 'Suurmestari', 'Grandmaster', NULL, 'Finland', 'Finnish', NULL, 2020, NULL, '40 - 42 min', 'https://www.mtv.fi/ohjelma/e7f959c4b762e341d082/suurmestari', 'https://www.imdb.com/title/tt12131806/', 'https://fi.wikipedia.org/wiki/Suurmestari_(televisiosarja)', NULL, NULL, 'Suurmestari is a Finnish TV programme on MTV3, based on the British Taskmaster TV show, in which competitors perform various tasks that they are assigned by the Suurmestari [Grandmaster]. Jaakko Saariluoma is the Suurmestari, assisted by Pilvi Hämäläinen. The regular contestants are joined by a guest contestant in each episode.', 'The panel consists of four fixed contestants, and a different guest contestant in each episode.|People who have previously appeared as guest contestants in a season may reappear in a later season as fixed contestants.|The guest contestants are not considered a team, for the purposes of the season scores, and so may not win the season.', 'There are only very rarely team tasks in this version of the show.', 'There are no tie-breakers in this version of the show. Episodes with tied scores are left as draws, with the contestants sharing the prize pool.', 'A prize pool is established for each episode from items brought in by contestants for the prize task.|The prizes are typically presented on screen.|Starting in season 4, the format of the prize task segment changed, with Pilvi presenting the contestants\' prize submissions, rather than the contestants doing it themselves.', 'Season 1: Kultainen Venla, in the category of Best Game Show (2020)|Season 2: Kultainen Venla, in the category of Best Game Show (2021)|Season 3: Kultainen Venla, in the category of Best Game Show (2022)|Season 4: Kultainen Venla, in the category of Best Game Show (2023)|Season 5: Kultainen Venla, in the category of Best Game Show (2024)', NULL, '09_suurmestari_framed.png', '09_suurmestari_metatag.jpg', '09_suurmestari_thumb.jpg', 'Cover image for the Finnish show Suurmestari, showing the hosts of the show, Jaakko Saariluoma and Pilvi Hämäläinen.', '09_suurmestari_seal.jpg', '09_suurmestari_trophy.jpg'),
(10, 1, 1, 'The Taskmaster', NULL, NULL, 'UK', 'English', NULL, 2010, 2011, '75 min in 2010; 90 min in 2011', NULL, NULL, NULL, NULL, NULL, 'The Taskmaster was a 2010 Edinburgh Festival Fringe show presented by Alex Horne. Throughout 2009, he set 20 comedians monthly tasks to complete. In the two-hour live show, he discussed each contestant’s attempts at each task, with a screen behind him showing photographs of their attempts. The show was followed up with the Taskmaster II live Edinburgh Fringe show, featuring just 10 contestants, in 2011.', 'In the first year of the show, the panel consisted of a staggering 20 contestants.|For the second year of the show, this was reduced to 10 contestants.', 'It does not appear that there were any team tasks in this version of the show.', 'Ties were settled with tie-breaker tasks, live on stage.', 'The only prizes in this version of the show were actual trophy cups.', NULL, NULL, '10_the_taskmaster_framed.png', '10_the_taskmaster_metatag.jpg', '10_the_taskmaster_thumb.jpg', 'Cover image for the live Edinburgh show The Taskmaster, showing the host of the show, Alex Horne.', NULL, NULL),
(11, 0, 12, 'Taskmaster Portugal', NULL, NULL, 'Portugal', 'Portuguese', NULL, 2022, NULL, '90 mins', 'https://www.rtp.pt/play/', 'https://www.imdb.com/title/tt18935036/', NULL, 'https://www.instagram.com/taskmasterpt/', NULL, 'Taskmaster PT is the Portuguese adaptation of the Taskmaster format, which started airing on RTP1 in March 2022. It is hosted by Vasco Palmeirim (as the Taskmaster) and Nuno Markl (as the assistant). Two eight-episode seasons of the show are currently produced each year. The show started including some completely original task ideas of its own in season 3.', 'The panel consists of four fixed contestants, and a different guest contestant in each episode.|The guest contestants throughout the season are not considered a team, for the purposes of the season scores, and so cannot collectively win the season.', 'There were no team tasks in the first season of  the show, but they were introduced from season 2.', 'It is assumed that episode ties will be broken through tiebreaker tasks, either pre-recorded or live in studio.|This remains to be confirmed.', 'A prize pool is established for each episode from items brought in by contestants for the prize task.', NULL, 'In September 2021 <a href=\"https://espalhafactos.com/2021/09/16/vasco-palmeirim-e-nuno-markl-juntam-se-em-taskmaster-novo-programa-de-humor-da-rtp1/\">it was announced</a> that Vasco Palmeirim and Nuno Markl would host a Portuguese version of Taskmaster, with production scheduled for October 2021, and a premiere in early 2022.|On his Instagram account <a href=\"https://www.instagram.com/p/CT5Zv5PM_e0/\">Nuno said</a> \"About two or three years ago, Vasco Palmeirim told me about the British program \'Taskmaster\' and how there should be a Portuguese version. And how the two of us should be doing it... we already have the blessing of the original creator, the great Alex Horne.\"|Since October 2021 Nuno has posted several photos from the production on his Instagram account, including one of <a href=\"https://www.instagram.com/p/CVx6crJs_dM/\">a Zoom call with Alex Horne</a>, and <a href=\"https://www.instagram.com/p/CWBWdZZM5ws/\">the corner of a throne on the studio set</a>.|On 23 January 2022 an <a href=\"https://magg.sapo.pt/televisao/artigos/vasco-palmeirim-desvenda-pormenores-sobre-taskmaster-temos-ali-um-belissimo-programa\">article was published</a>, based on an interview with Vasco Palmeirim, in which it was disclosed that the first season of the show would have eight episodes.|On 27 January it was <a href=\"https://www.atelevisao.com/rtp/taskmaster-estreia-em-marco-na-rtp1/\">disclosed in a post</a> on atelevisao.com that the show would begin airing on Saturdays, starting in March, and that the episodes would each be 90 minutes long. It is unclear whether this is the total run time, including ads, or the length of the show itself.|On 26 February the <a href=\"https://www.instagram.com/p/CacwRxulLXv/\">first video footage</a> from the season was shared on the official TaskmasterPT Instagram account. The text on the envelope at the end of the video did not give any air date, instead simply indicating that the show would be coming \'soon\'.|On 9 March 2022 it was officially announced, <a href=\"https://www.instagram.com/stories/taskmasterpt/2790136880913842855/\">via an Instagram story</a>, that the show would begin airing on 19 March 2022.', '11_taskmaster_pt_framed.png', '11_taskmaster_pt_metatag.jpg', '11_taskmaster_pt_thumb.jpg', 'Cover image for the Portuguese show Taskmaster PT, showing the hosts of the show, Vasco Palmeirim and Nuno Markl.', '11_taskmaster_pt_seal.jpg', NULL),
(12, 0, 11, 'Direktor Svemira', 'Director of the Universe', NULL, 'Croatia', 'Croatian', NULL, 2021, 2021, '45 - 60 min', 'https://www.rtl.hr/tv/programi/zabava/17682/direktor-svemira/', NULL, NULL, 'https://www.instagram.com/direktor_svemira_rtl/', NULL, 'Direktor Svemira was the Croatian version of Taskmaster, and began airing on RTL Croatia in November 2021 with its first series of ten episodes. The show was hosted by Taskmaster Ivan Saric and his assistant Luka Petrusic.|Based on an <a target=\"_blank\" href=\"https://avalonuk.com/2022/10/06/taskmaster-travels-down-under/\">Avalon press release</a>, it was originally anticipated that season 2 of Direktor Svemira would begin airing in late 2022. However, given that there has subsequently been no further publicity for the season, it is now assumed that this season has been axed by RTL, despite the fact that production was already completed.', 'The panel consists of five fixed contestants per season.', 'Team tasks are completed by uneven teams of two and three contestants.', 'There have not yet been any tied episodes in this version of the show, so it is not known if or how ties might be settled.', 'A prize pool is established for each episode from items brought in by contestants for the prize task.|The prizes are typically presented on screen.', NULL, 'In November 2021 the Croatian comedian Ivan Saric posted a <a href=\"https://www.instagram.com/stories/ivansaric/2703390074958058394/\">story on his Instagram account</a>, showing what appeared to be the stage production of a Taskmaster show, featuring the hashtag \'#soon\'.|A source who claimed to have a connection to one of the contestants shared in a <a href=\"https://www.reddit.com/r/taskmaster/comments/qqj82b/taskmaster_croatia_in_the_making/\">Reddit thread</a> that: Ivan would be serving in the Taskmaster role for the show, which would be named <em>Direktor Svemira</em> (roughly translating as \'Director of the Universe\'); it was being produced by - and would air on - RTL, a Croatian free-to-air TV network; and the show may begin airing as early as late November/early December.|On 12 November 2021 RTL put an an <a href=\"https://www.rtl.hr/tv/tv-novosti/4138488/neobicni-zadaci-poznati-gosti-i-puno-smijeha-uz-ivana-sarica-i-luku-petrusica-u-novom-showu-direktor-svemira/\">official press release</a>, confirming that the Taskmaster would be Ivan Saric and his assistant would be the actor Luka Petrusic.|The same day, Ivan published <a href=\"https://www.instagram.com/p/CWLKtZlM1NA/\">several photos of himself and his co-host</a> on his Instagram account.|On 14 November Luka published <a href=\"https://www.instagram.com/p/CWRZ_hNs2vy/\">a photo of the studio set</a> to his Instagram account.|On 15 November RTL disclosed <a href=\"https://www.rtl.hr/tv/tv-novosti/4139926/svjetski-nagradjivani-show-taskmaster-nastao-je-sasvim-slucajno-a-evo-kad-cete-ga-gledati-na-rtl-u/\">in a new press release</a> that the show would air on Wednesday and Thursday evenings (i.e. two episodes per week), starting on 24 November.', '12_direktor_svemira_framed.png', '12_direktor_svemira_metatag.jpg', '12_direktor_svemira_thumb.jpg', 'Cover image for the Croatian show Direktor Svemira, showing the hosts of the show, Ivan Saric and Luka Petrusic.', '12_direktor_svemira_seal.jpg', NULL),
(13, 0, 13, 'Le Maître du Jeu', 'The Master of Games', NULL, 'Canada', 'French', NULL, 2022, NULL, '43 - 44 minutes', 'https://www.noovo.ca/emissions/le-maitre-du-jeu', 'https://www.imdb.com/title/tt29416057/', NULL, NULL, NULL, 'Le Maître du Jeu is the Quebecois adaptation of the Taskmaster format, the first season of which began airing on the French-Canadian Noovo TV network in September 2022.|The show is hosted by Louis Morissette (in the Taskmaster role) and Antoine Vézina (in the assistant role).', 'The show has a fixed panel of five contestants.', 'The show includes team tasks, completed by uneven teams of two and three contestants.', 'There are no tie-breakers in this version of the show. Episodes with tied scores are left as draws, with the contestants sharing the prize pool.', 'A prize pool is established for each episode from items brought in by contestants for the prize task.|The prizes are typically presented on screen.', NULL, 'This adaptation of the show was first announced in the Canadian press on 12 April 2022 (<a href=\"https://ctvm.info/le-maitre-du-jeu-louis-morissette-a-la-barre-de-la-version-quebecoise-du-succes-international-taskmaster-a-noovo-cet-automne/\">CVTM article</a> / <a href=\"https://hollywoodpq.com/louis-morissette-le-maitre-du-jeu/\">Hollywood PQ article</a>).', '13_le_maitre_du_jeu_framed.png', '13_le_maitre_du_jeu_metatag.jpg', '13_le_maitre_du_jeu_thumb.jpg', 'Cover image for the Quebecois show Le Maître du Jeu, showing the hosts of the show, Louis Morissette and Antoine Vézina.', '13_le_maitre_du_jeu_seal.jpg', '13_le_maitre_du_jeu_trophy.jpg'),
(14, 0, 14, 'Taskmaster Australia', NULL, 'On Sweden\'s TV4 Play service, this show is titled \'Bäst i test Australien\' (Best in Test Australia).|On Finland\'s MTV3 service, this show is titled \'Suurmestari Australia\' (Grandmaster Australia).', 'Australia', 'English', NULL, 2023, NULL, '45 - 47 minutes', 'https://10play.com.au/taskmaster', 'https://www.imdb.com/title/tt25523050/', 'https://en.wikipedia.org/wiki/Taskmaster_Australia', 'https://www.instagram.com/taskmasteraustralia/', NULL, 'Taskmaster AU is the Australian adaptation of the Taskmaster format, commissioned by Paramount, and produced by Avalon Television in partnership with Kevin & Co (the production company for Taskmaster NZ) for Network 10.|The show is hosted by Tom Gleeson (as the Taskmaster) and Tom Cashman (as his assistant).|The first season of the show, consisting of 10 episodes, began airing in February 2023.', NULL, NULL, NULL, NULL, NULL, 'On 6 October 2022 it was officially announced by <a href=\"https://avalonuk.com/2022/10/06/taskmaster-travels-down-under/\">Avalon</a> and the Australian TV channel <a href=\"https://twitter.com/Channel10AU/status/1577845802726174720\">Channel 10</a> (after several months of online rumours) that an Australian version of Taskmaster was in production, and would begin airing in 2023.|Chief task writer for Taskmaster NZ, Sam Smith, also <a href=\"https://twitter.com/ReelBigSmith/status/1577861898737180673\">shared</a> that he had been involved in writing tasks for the new version of the show, and also <a href=\"https://twitter.com/ReelBigSmith/status/1577873465067327488\">confirmed</a> that the show was being filmed in New Zealand.', '14_taskmaster_au_framed.png', '14_taskmaster_au_metatag.jpg', '14_taskmaster_au_thumb.jpg', 'Cover image for the Australian show Taskmaster AU, showing the hosts of the show, Tom Gleeson and Tom Cashman.', '14_taskmaster_au_seal.jpg', '14_taskmaster_au_trophy.jpg'),
(15, 1, 15, 'Junior Taskmaster', NULL, NULL, 'UK', 'English', NULL, 2024, 2024, NULL, NULL, NULL, NULL, NULL, NULL, 'Junior Taskmaster UK was a version of the Taskmaster UK format, aimed at and featuring children aged between 9 and 11, which was commissioned by Channel 4.|The show was hosted by Rose Matafeo (as the Taskmaster), and Mike Wozniak (as her assistant), and was structured as a tournament, with the first five episodes of each series featuring five new contestants, who competed to qualify for the semi-finals, and then a grand final.|The filmed tasks took place at a different location to the original Taskmaster UK house, and the studio segments were filmed at Television Centre, but using the same set as the adult version of the show.|The first series aired in 2024. As there has not yet been any news of a second series, it is assumed that the show was not renewed.', NULL, NULL, NULL, NULL, 'Royal Television Society Programme Award, in the category of Comedy Entertainment (2025).', 'On 15 March 2023, it was <a href=\"https://deadline.com/2023/03/channel-4-taskmaster-junior-version-six-season-renewal-avalon-1235297833/\">reported</a> that Channel 4 had commissioned a season of Junior Taskmaster, in addition to six further seasons of the original Taskmaster UK show.|On 18 April 2023, SRO Audiences opened up <a href=\"https://www.sroaudiences.com/application.asp?show_id=385\">applications</a> for tickets to attend two test-run studio filming sessions for the show at Pinewood Studios on 16 May 2023.|On 16 May 2023, as studio filming for the test-runs of the show began at Pinewood Studios, it was <a href=\"https://avalonuk.com/2023/05/16/rose-matafeo-and-mike-wozniak-confirmed-as-the-junior-taskmaster-and-assistant-in-channel-4s-brand-new-junior-taskmaster/\">announced</a> that the hosts of the show would be Rose Matafeo and Mike Wozniak.|On 25 May 2023, the application process for contestants for the first series of Junior Taskmaster opened up <a target=\"_blank\" href=\"https://eu.castitreach.com/ag/avalontm/juniortaskmaster/welcome.html\">via CastItReach</a>.', '15_junior_taskmaster_framed.png', '15_junior_taskmaster_metatag.jpg', '15_junior_taskmaster_thumb.jpg', 'Cover image for the UK show Junior Taskmaster, showing the hosts of the show, Rose Matafeo and Mike Wozniak.', '15_junior_taskmaster_seal.jpg', '15_junior_taskmaster_trophy.jpg'),
(16, 1, 16, 'Juniori Suurmestari', 'Junior Grandmaster', NULL, 'Finland', 'Finnish', NULL, 2024, 2024, NULL, NULL, NULL, NULL, NULL, NULL, 'Juniori Suurmestari was a version of the Finnish adaptation of the Taskmaster format featuring contestants aged between 8 and 12.|The show was presented by the same hosts as the adult version of the show: Jaakko Saariluoma (as the Taskmaster) and Pilvi Hämäläinen (as his assistant).|The first season aired at the end of 2024. Since there has not been any news of a second season, it is assumed that the show was not renewed.', 'A fixed panel of contestants aged between 8 and 12 years appears on every episode of the show, in contrast to the adult version which has a different guest contestant in the fifth seat each week.', 'No team tasks have yet been used in this version of the show.', 'No tie-breaker tasks have yet been used on the show.', 'A prize pool is established for each episode from items brought in by contestants for the prize task.|The prizes are typically presented on screen.|The contestants present their own prizes in this version of the show, in contrast to the adult version, in which Pilvi took over presentation of the prizes in season 4.', NULL, 'On March 1st 2024, it was <a target=\"_blank\" href=\"https://www.mtvuutiset.fi/artikkeli/juniori-suurmestari-tulee-hae-mukaan-ohjelmaan/8888366#gs.5wk1lx\">announced</a> that a version of Suurmestari for kids aged between 8 and 12 was beginning production.', '16_juniori_suurmestari_framed.png', '16_juniori_suurmestari_metatag.jpg', '16_juniori_suurmestari_thumb.jpg', 'Cover image for the Finnish show Juniori Suurmestari, showing one of the hosts of the show, Jaakko Saariluoma.', '09_suurmestari_seal.jpg', '09_suurmestari_trophy.jpg'),
(17, NULL, 17, 'Taskmaster Netherlands', NULL, NULL, 'Netherlands', 'Dutch', NULL, 2026, NULL, '60 minutes', NULL, NULL, NULL, NULL, NULL, 'RTL Nederland has commissioned the production of two 8-episode seasons of Taskmaster for broadcast in the Netherlands. The 60 minute show will be produced by The Human Factor, and will feature the presenter and comedian Arjen Lubach as the Taskmaster.', NULL, NULL, NULL, NULL, NULL, 'This is not the first attempt at a Dutch version of the Taskmaster format. Back on the 4th of July 2019, two pilot episodes were recorded, featuring <a target=\"_blank\" href=\"https://nl.wikipedia.org/wiki/Peter_Pannekoek\">Peter Pannekoek</a> in the Taskmaster role and a member of the cast of <em><a target=\"_blank\" href=\"https://nl.wikipedia.org/wiki/Foute_Vrienden_(RTL)\">Foute Vrienden</a></em> (the Dutch version of Impractical Jokers) as his assistant. Among the cast members for the pilot was <a target=\"_blank\" href=\"https://nl.wikipedia.org/wiki/Thomas_Acda\">Thomas Acda</a>. However, the pilots did not lead to the commission of a full series at that time.|On the 3rd of March 2025, it was <a target=\"_blank\" href=\"https://www.rtl.nl/boulevard/entertainment/artikel/5497308/arjen-lubach-taskmaster-rtl\">reported</a> that the comedian and presenter Arjen Lubach and his production company Human Factor TV had produced a new pilot episode of a Dutch version of Taskmaster, with Arjen in the titular role, and that a full season of the show would air in 2026 on RTL 4 or Videoland, or both.|On the 15th of October 2025, it was <a target=\"_blank\" href=\"https://www.c21media.net/news/three-new-european-versions-of-taskmaster-extend-avalon-formats-global-footprint/\">reported</a> that RTL Nederland had commissioned the production of two 8-episode seasons of Taskmaster for broadcast in the Netherlands.', NULL, NULL, NULL, NULL, NULL, NULL),
(18, NULL, 18, 'Taskmaster Iceland', NULL, NULL, 'Iceland', 'Icelandic', NULL, 2026, NULL, '60 minutes', NULL, NULL, NULL, NULL, NULL, 'The Icelandic media company Sýn has commissioned the production of a 10-episode season of Taskmaster for broadcast in Iceland. The 60 minute show will be produced by Sagafilm. Neither the hosts nor the anticipated broadcast date have yet been announced.', NULL, NULL, NULL, NULL, NULL, 'On the 15th of October 2025, it was <a target=\"_blank\" href=\"https://www.c21media.net/news/three-new-european-versions-of-taskmaster-extend-avalon-formats-global-footprint/\">reported</a> that the Icelandic media company Sýn had commissioned the production of a 10-episode season of Taskmaster for broadcast in Iceland.', NULL, NULL, NULL, NULL, NULL, NULL),
(19, NULL, 19, 'Taskmaster Estonia', NULL, NULL, 'Estonia', 'Estonian', NULL, 2026, NULL, '90 minutes', NULL, NULL, NULL, NULL, NULL, 'The Estonian channel TV3 has commissioned the production of a 12-episode season of Taskmaster for broadcast in Estonia. The 90 minute show will be produced by Thor Films. Neither the hosts nor the anticipated broadcast date have yet been announced.', NULL, NULL, NULL, NULL, NULL, 'On the 15th of October 2025, it was <a target=\"_blank\" href=\"https://www.c21media.net/news/three-new-european-versions-of-taskmaster-extend-avalon-formats-global-footprint/\">reported</a> that the Estonian channel TV3 had commissioned the production of a 12-episode season of Taskmaster for broadcast in Estonia.', NULL, NULL, NULL, NULL, NULL, NULL);
